import { FormEvent, ReactNode, useEffect, useMemo, useRef, useState } from 'react'
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query'
import {
  Activity, AlertTriangle, ArrowDownToLine, AudioLines, BookOpenCheck, Cable, Check, ChevronDown,
  ChevronRight, CircleHelp, Clock3, Command, Cpu, Database, FileClock, Gauge, GitBranch, LayoutDashboard,
  ListFilter, LoaderCircle, Menu, Moon, Plus, Radio, RefreshCw, Search, Settings2, Shield, SlidersHorizontal,
  Sun, TerminalSquare, Trash2, X,
} from 'lucide-react'
import { api, EventRow, Gateway, getToken, Measurement, Node, Overview, patch, PollItem, post, put, setToken } from './api'
import PipelinePage from './PipelinePage'

type Page = 'Overview' | 'Input Nodes' | 'Output Nodes' | 'Modbus Polling' | 'Live Telemetry' | 'Calibration' | 'I/O Pipelines' | 'Communication Logs' | 'Settings'

const navigation: { label: Page; icon: typeof Activity; section: string }[] = [
  { label: 'Overview', icon: LayoutDashboard, section: 'Monitor' },
  { label: 'Input Nodes', icon: AudioLines, section: 'Monitor' },
  { label: 'Output Nodes', icon: Cable, section: 'Monitor' },
  { label: 'Modbus Polling', icon: SlidersHorizontal, section: 'Configure' },
  { label: 'Live Telemetry', icon: Activity, section: 'Configure' },
  { label: 'Calibration', icon: Gauge, section: 'Configure' },
  { label: 'I/O Pipelines', icon: GitBranch, section: 'Configure' },
  { label: 'Communication Logs', icon: FileClock, section: 'System' },
  { label: 'Settings', icon: Settings2, section: 'System' },
]

const categories = ['Analog Measurements', 'Device Information', 'Analog Configuration', 'Trigger Configuration', 'Network Configuration', 'Custom Registers']
const fmtTime = (value?: string | null) => value ? new Date(value).toLocaleString([], { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit', second: '2-digit' }) : 'No successful read'
const relativeTime = (value?: string | null) => {
  if (!value) return 'No data'
  const seconds = Math.max(0, Math.floor((Date.now() - new Date(value).getTime()) / 1000))
  return seconds < 60 ? `${seconds}s ago` : seconds < 3600 ? `${Math.floor(seconds / 60)}m ago` : `${Math.floor(seconds / 3600)}h ago`
}
const labelForNode = (node?: Node) => node ? `${node.name} · ${node.hardware_model || node.node_type.replace('_', ' ')}` : 'Select node'

function Status({ good, warning, children }: { good?: boolean; warning?: boolean; children: ReactNode }) {
  return <span className={`state ${good ? 'good' : warning ? 'warning' : ''}`}><i className="status-dot" />{children}</span>
}

function PageHeading({ title, description, right }: { title: string; description: string; right?: ReactNode }) {
  return <div className="page-head"><div><h1>{title}</h1><p>{description}</p></div>{right}</div>
}

function Panel({ title, note, action, children }: { title: string; note?: string; action?: ReactNode; children: ReactNode }) {
  return <section className="panel"><div className="panel-head"><div><div className="panel-title">{title}</div>{note && <div className="panel-note" style={{ marginTop: 3 }}>{note}</div>}</div>{action}</div>{children}</section>
}

function Empty({ title, children }: { title: string; children?: ReactNode }) {
  return <div className="empty"><strong>{title}</strong>{children}</div>
}

function Modal({ title, onClose, children }: { title: string; onClose: () => void; children: ReactNode }) {
  useEffect(() => { const onKey = (e: KeyboardEvent) => e.key === 'Escape' && onClose(); window.addEventListener('keydown', onKey); return () => window.removeEventListener('keydown', onKey) }, [onClose])
  return <div className="modal-backdrop" onMouseDown={e => e.target === e.currentTarget && onClose()}><div className="modal" role="dialog" aria-modal="true" aria-label={title}><div className="modal-head"><strong>{title}</strong><button className="icon-button" aria-label="Close dialog" onClick={onClose}><X size={16} /></button></div><div className="modal-body">{children}</div></div></div>
}

function Login({ onLogin }: { onLogin: (token: string) => void }) {
  const [value, setValue] = useState('')
  const [error, setError] = useState('')
  const [busy, setBusy] = useState(false)
  async function submit(e: FormEvent) {
    e.preventDefault(); setBusy(true); setError('')
    setToken(value)
    try { await api('/api/overview'); onLogin(value) }
    catch (err) { setToken(''); setError(err instanceof Error ? err.message : 'Could not connect to the service') }
    finally { setBusy(false) }
  }
  return <main className="login-wrap"><section className="login-panel"><div className="brand" style={{ padding: 0 }}><span className="brand-mark"><AudioLines size={18} /></span>Fieldline <span style={{ color: 'var(--muted)', fontWeight: 450 }}>I/O Monitor</span></div><h1>Connect to your service</h1><p>Enter the administrator API token configured on the backend. The token is kept in this browser for this session.</p><form onSubmit={submit}><div className="field"><label htmlFor="token">Administrator token</label><input id="token" className="input" type="password" value={value} onChange={e => setValue(e.target.value)} autoComplete="current-password" required /></div>{error && <p className="error" role="alert">{error}</p>}<button className="button primary" style={{ width: '100%', marginTop: 14 }} disabled={busy}>{busy ? <LoaderCircle size={15} className="spin" /> : <Shield size={15} />} Connect</button></form></section></main>
}

function App() {
  const queryClient = useQueryClient()
  const [token, updateToken] = useState(getToken())
  const [page, setPage] = useState<Page>('Overview')
  const [mobileOpen, setMobileOpen] = useState(false)
  const [theme, setTheme] = useState(localStorage.getItem('fieldline-theme') || 'light')
  useEffect(() => { document.documentElement.dataset.theme = theme; localStorage.setItem('fieldline-theme', theme) }, [theme])
  useEffect(() => { const clear = () => updateToken(''); window.addEventListener('fieldline-auth-expired', clear); return () => window.removeEventListener('fieldline-auth-expired', clear) }, [])
  const health = useQuery({ queryKey: ['health', token], queryFn: () => api<{ service: string }>('/api/health'), enabled: !!token, refetchInterval: 5000, retry: false })
  if (!token) return <Login onLogin={value => updateToken(value)} />
  return <div className="app-shell">
    <button className={`sidebar-backdrop ${mobileOpen ? 'open' : ''}`} aria-label="Close navigation" onClick={() => setMobileOpen(false)} />
    <aside className={`sidebar ${mobileOpen ? 'open' : ''}`}>
      <div className="brand"><span className="brand-mark"><AudioLines size={17} /></span><span>Fieldline</span><span style={{ color: 'var(--muted)', fontSize: 11, fontWeight: 450 }}>I/O</span></div>
      {['Monitor', 'Configure', 'System'].map(section => <div key={section}><div className="nav-label">{section}</div>{navigation.filter(item => item.section === section).map(item => { const Icon = item.icon; return <button key={item.label} className={`nav-item ${page === item.label ? 'active' : ''}`} onClick={() => { setPage(item.label); setMobileOpen(false) }}><Icon size={16} strokeWidth={1.8} />{item.label}</button> })}</div>)}
      <div className="sidebar-foot">Gateway TCP · Port 5001<br />AO writes need operator arming</div>
    </aside>
    <div className="workspace">
      <header className="topbar"><div style={{ display: 'flex', alignItems: 'center', gap: 12 }}><button className="icon-button mobile-menu" aria-label="Open navigation" onClick={() => setMobileOpen(true)}><Menu size={17} /></button><span className="crumb">Fieldline <ChevronRight size={12} style={{ verticalAlign: 'middle', margin: '0 5px' }} /> {page}</span></div><div className="top-actions"><span className="sync-status"><i className={`status-dot ${health.isSuccess ? 'good' : ''}`} /><span className="sync-label">Backend {health.isSuccess ? 'connected' : health.isPending ? 'checking' : 'disconnected'}</span></span><button className="icon-button" aria-label={`Switch to ${theme === 'light' ? 'dark' : 'light'} theme`} onClick={() => setTheme(theme === 'light' ? 'dark' : 'light')}>{theme === 'light' ? <Moon size={16} /> : <Sun size={16} />}</button><button className="icon-button" aria-label="Disconnect" title="Disconnect" onClick={() => { setToken(''); updateToken(''); queryClient.clear() }}><X size={16} /></button></div></header>
      <main className="content"><div className="signal-rail" aria-hidden="true"><span />{Array.from({ length: 12 }, (_, i) => <span key={i} />)}</div>
        {page === 'Overview' && <OverviewPage onNavigate={setPage} />}
        {page === 'Input Nodes' && <NodesPage type="ANALOG_INPUT" />}
        {page === 'Output Nodes' && <NodesPage type="ANALOG_OUTPUT" />}
        {page === 'Modbus Polling' && <PollingPage />}
        {page === 'Live Telemetry' && <TelemetryPage />}
        {page === 'Calibration' && <CalibrationPage />}
        {page === 'I/O Pipelines' && <PipelinePage />}
        {page === 'Communication Logs' && <LogsPage />}
        {page === 'Settings' && <SettingsPage theme={theme} setTheme={setTheme} />}
      </main>
    </div>
  </div>
}

function OverviewPage({ onNavigate }: { onNavigate: (page: Page) => void }) {
  const query = useQuery({ queryKey: ['overview'], queryFn: () => api<Overview>('/api/overview'), refetchInterval: 3000 })
  const data = query.data
  if (query.isError) return <><PageHeading title="Overview" description="Live gateway, Modbus and measurement status." /><Empty title="Backend data is unavailable">{(query.error as Error).message}. Check the API connection, then refresh.</Empty><button className="button" onClick={() => query.refetch()}><RefreshCw size={14} /> Retry</button></>
  return <>
    <PageHeading title="Overview" description="Gateway links and Modbus health are reported separately." right={<span className="head-meta">Updated {data ? relativeTime(data.last_measurement_at) : '-'}</span>} />
    <div className="metrics">
      <Metric label="Input nodes" value={data?.inputs.total ?? '-'} detail={`${data?.inputs.gateway_connected ?? 0} gateway · ${data?.inputs.disconnected ?? 0} disconnected · ${data?.inputs.unassigned ?? 0} unassigned · ${data?.inputs.modbus_responding ?? 0} Modbus`} icon={<AudioLines size={15} />} />
      <Metric label="Output nodes" value={data?.outputs.total ?? '-'} detail={`${data?.outputs.gateway_connected ?? 0} gateway · ${data?.outputs.disconnected ?? 0} disconnected · ${data?.outputs.unassigned ?? 0} unassigned · ${data?.outputs.health_unknown ?? 0} health unknown`} icon={<Cable size={15} />} />
      <Metric label="Poll items active" value={data?.polling.active ?? '-'} detail={`${data?.polling.failed ?? 0} errors recorded`} icon={<Activity size={15} />} />
      <Metric label="Average response" value={data?.polling.average_response_ms == null ? '-' : `${data.polling.average_response_ms.toFixed(1)} ms`} detail={`${data?.polling.successful ?? 0} valid responses`} icon={<Clock3 size={15} />} />
    </div>
    <div className="split-grid">
      <Panel title="Registered nodes" note="Gateway presence does not confirm a Modbus response." action={<button className="button small" onClick={() => onNavigate('Input Nodes')}>View nodes <ChevronRight size={13} /></button>}>
        {data?.nodes.length ? <div className="table-wrap"><table><thead><tr><th>Node</th><th>Gateway</th><th>Slave</th><th>Gateway</th><th>Modbus</th><th>Last data / communication</th></tr></thead><tbody>{data.nodes.slice(0, 8).map(node => <tr key={node.id}><td><div className="primary-name">{node.name}</div><div className="secondary">{node.hardware_model || node.node_type.replace('_', ' ')}</div></td><td>{node.gateway_id?.slice(0, 8) ?? 'Unassigned'}</td><td>{node.slave_id}</td><td><Status good={node.gateway_connected}>{node.gateway_state || (node.gateway_connected ? 'CONNECTED' : 'UNKNOWN')}</Status></td><td><Status good={node.modbus_healthy} warning={!!node.gateway_connected && !node.modbus_healthy}>{node.modbus_health || 'UNKNOWN'}</Status></td><td>{relativeTime(node.node_type === 'ANALOG_OUTPUT' ? node.last_modbus_at : node.last_measurement_at)}</td></tr>)}</tbody></table></div> : <Empty title="No nodes registered">Add a gateway and input node to begin commissioning.</Empty>}
      </Panel>
      <div style={{ display: 'grid', gap: 18 }}>
        <Panel title="System health" note="Current backend and transport state"><div className="panel-body health-list"><HealthLine label="Backend service" value="Connected" good /><HealthLine label="Gateway sessions" value={`${data?.gateway_connections.connected ?? 0} / ${data?.gateway_connections.total ?? 0}`} good={!!data?.gateway_connections.connected} /><HealthLine label="Polling scheduler" value={data?.polling.state ?? 'Checking'} good={data?.polling.state === 'RUNNING'} /><HealthLine label="Latest measurement" value={relativeTime(data?.last_measurement_at)} good={!!data?.last_measurement_at} /></div></Panel>
        <Panel title="Recent communication" action={<button className="button small" onClick={() => onNavigate('Communication Logs')}>Open logs <ChevronRight size={13} /></button>}>
          <div className="panel-body">{data?.recent_events.length ? data.recent_events.slice(0, 5).map(event => <EventLine key={event.id} event={event} />) : <Empty title="No communication events">Events appear after a gateway connects or a polling request runs.</Empty>}</div>
        </Panel>
      </div>
    </div>
    <div style={{ marginTop: 18 }}><Panel title="I/O readiness" note="No output commands are sent by this service."><div className="panel-body health-list"><HealthLine label="Input measurements" value={data?.inputs.total ? `${data.inputs.total} nodes configured` : 'Not configured'} good={!!data?.inputs.total} /><HealthLine label="Output integration" value="Planned · writes disabled" /></div></Panel></div>
  </>
}

function Metric({ label, value, detail, icon }: { label: string; value: string | number; detail: string; icon: ReactNode }) {
  return <div className="metric"><div className="metric-label"><span>{label}</span><span>{icon}</span></div><div className="metric-value">{value}<span className="metric-sub">{detail}</span></div></div>
}
function HealthLine({ label, value, good, warning }: { label: string; value: string; good?: boolean; warning?: boolean }) { return <div className="health-line"><span>{label}</span><Status good={good} warning={warning}>{value}</Status></div> }
function EventLine({ event }: { event: EventRow }) { return <div className="event-row"><span className="event-time">{new Date(event.at).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' })}</span><span className="event-detail" title={event.detail}>{event.detail}</span><span className="event-result">{event.result}</span></div> }

function NodesPage({ type }: { type: Node['node_type'] }) {
  const queryClient = useQueryClient()
  const [search, setSearch] = useState('')
  const [showAdd, setShowAdd] = useState(false)
  const [selected, setSelected] = useState<Node | null>(null)
  const [notice, setNotice] = useState('')
  const nodesQuery = useQuery({ queryKey: ['nodes', type], queryFn: () => api<Node[]>(`/api/nodes?type=${type}`) })
  const gatewaysQuery = useQuery({ queryKey: ['gateways'], queryFn: () => api<Gateway[]>('/api/gateways') })
  const nodes = (nodesQuery.data || []).filter(node => `${node.name} ${node.hardware_model} ${node.id}`.toLowerCase().includes(search.toLowerCase()))
  const mutation = useMutation({ mutationFn: (data: unknown) => post('/api/nodes', data), onSuccess: () => { queryClient.invalidateQueries({ queryKey: ['nodes'] }); queryClient.invalidateQueries({ queryKey: ['overview'] }); setShowAdd(false) } })
  const title = type === 'ANALOG_INPUT' ? 'Input nodes' : 'Output nodes'
  return <>
    <PageHeading title={title} description={type === 'ANALOG_INPUT' ? 'Register and inspect EBYTE ME31-XAXX0600 analog input devices.' : 'Manage EBYTE ME31-XXXA0006 setpoints with acknowledged manual output tests.'} right={<button className="button primary" onClick={() => setShowAdd(true)}><Plus size={15} /> Add node</button>} />
    {notice && <div className="notice info" role="status">{notice}</div>}
    <div className="toolbar"><div style={{ position: 'relative', width: 'min(320px,100%)' }}><Search size={14} style={{ position: 'absolute', left: 10, top: 11, color: 'var(--muted)' }} /><input className="input" style={{ paddingLeft: 32 }} placeholder="Search name, model or ID" value={search} onChange={e => setSearch(e.target.value)} /></div><span className="panel-note">{nodes.length} registered</span></div>
    <Panel title="Node registry" note="Identity is independent of gateway IP and TCP source port.">
      {nodesQuery.isLoading ? <Empty title="Loading node registry">Reading saved configuration.</Empty> : nodesQuery.isError ? <Empty title="Could not load nodes">{(nodesQuery.error as Error).message}</Empty> : nodes.length ? <div className="table-wrap"><table><thead><tr><th>Name</th><th>Hardware model</th><th>Gateway</th><th>Slave ID</th><th>Channels</th><th>Gateway session</th><th>Modbus</th><th>Polling</th><th>Last data / communication</th></tr></thead><tbody>{nodes.map(node => <tr key={node.id} data-clickable="true" onClick={() => setSelected(node)}><td><div className="primary-name">{node.name}</div><div className="secondary">{node.id}</div></td><td>{node.hardware_model || 'Not specified'}</td><td>{node.gateway_id?.slice(0, 8) || 'Unassigned'}</td><td>{node.slave_id}</td><td>{node.enabled_channel_count ?? 0}</td><td><Status good={node.gateway_connected}>{node.gateway_state || (node.gateway_connected ? 'CONNECTED' : 'UNKNOWN')}</Status></td><td><Status good={node.modbus_healthy} warning={!!node.gateway_connected && !node.modbus_healthy}>{node.modbus_health || 'UNKNOWN'}</Status></td><td>{node.polling_enabled ? 'Enabled' : 'Disabled'}</td><td>{relativeTime(node.node_type === 'ANALOG_OUTPUT' ? node.last_modbus_at : node.last_measurement_at)}</td></tr>)}</tbody></table></div> : <Empty title={search ? 'No matching nodes' : 'No nodes registered'}>{search ? 'Try another search.' : 'Register this device to begin configuration.'}</Empty>}
    </Panel>
    {showAdd && <Modal title={`Register ${type === 'ANALOG_INPUT' ? 'input' : 'output'} node`} onClose={() => setShowAdd(false)}><form onSubmit={e => { e.preventDefault(); const form = new FormData(e.currentTarget); mutation.mutate({ name: form.get('name'), node_type: type, gateway_id: form.get('gateway_id') || null, slave_id: Number(form.get('slave_id')) }) }}><div className="notice info">Device profile is fixed to {type === 'ANALOG_INPUT' ? 'EBYTE ME31-XAXX0600 · six AI channels' : 'EBYTE ME31-XXXA0006 · six AO channels'}.</div><div className="form-grid"><Field label="Display name"><input className="input" name="name" required maxLength={100} placeholder={type === 'ANALOG_INPUT' ? 'Plant input 01' : 'Plant output 01'} /></Field><Field label="Assigned gateway"><select className="select" name="gateway_id"><option value="">No gateway assigned</option>{gatewaysQuery.data?.filter(gateway => gateway.transport_mode === (type === 'ANALOG_INPUT' ? 'MODBUS_TCP' : 'TRANSPARENT_SERIAL')).map(gateway => <option value={gateway.id} key={gateway.id}>{gateway.name} · {gateway.transport_mode}</option>)}</select></Field><Field label="Modbus slave ID"><input className="input" name="slave_id" type="number" defaultValue="1" min="1" max="247" required /></Field></div>{mutation.isError && <p className="error">{(mutation.error as Error).message}</p>}<div className="form-actions"><button type="button" className="button" onClick={() => setShowAdd(false)}>Cancel</button><button className="button primary" disabled={mutation.isPending}>{mutation.isPending ? 'Saving…' : 'Save node'}</button></div></form></Modal>}
    {selected && <NodeDetails node={selected} onClose={() => setSelected(null)} onDeleted={name => { setNotice(`${name} archived. Measurement and audit history has been preserved.`); setSelected(null) }} />}
  </>
}

function NodeDetails({ node, onClose, onDeleted }: { node: Node; onClose: () => void; onDeleted: (name: string) => void }) {
  const queryClient = useQueryClient()
  const [name, setName] = useState(node.name)
  const [slaveId, setSlaveId] = useState(String(node.slave_id))
  const [gatewayId, setGatewayId] = useState(node.gateway_id || '')
  const [enabled, setEnabled] = useState(!!node.polling_enabled)
  const [confirmDelete, setConfirmDelete] = useState(false)
  const mutation = useMutation({ mutationFn: (data: unknown) => patch(`/api/nodes/${node.id}`, data), onSuccess: () => { queryClient.invalidateQueries({ queryKey: ['nodes'] }); queryClient.invalidateQueries({ queryKey: ['overview'] }); onClose() } })
  const polling = useQuery({ queryKey: ['polling', node.id], queryFn: () => api<PollItem[]>(`/api/nodes/${node.id}/polling`) })
  const channels = useQuery({ queryKey: ['channels', node.id], queryFn: () => api<any[]>(`/api/nodes/${node.id}/channels`) })
  const gateways = useQuery({ queryKey: ['gateways'], queryFn: () => api<Gateway[]>('/api/gateways'), refetchInterval: 3000 })
  const outputState = useQuery({ queryKey: ['outputs', node.id], queryFn: () => api<any>(`/api/nodes/${node.id}/outputs`), enabled: node.node_type === 'ANALOG_OUTPUT', refetchInterval: 5000, retry: false })
  const [testChannel, setTestChannel] = useState(1)
  const [targetMa, setTargetMa] = useState('4')
  const manualSet = useMutation({ mutationFn: (body: unknown) => post(`/api/nodes/${node.id}/outputs/${testChannel}/set`, body), onSuccess: () => { queryClient.invalidateQueries({ queryKey: ['outputs', node.id] }); queryClient.invalidateQueries({ queryKey: ['logs'] }) } })
  const testRange = outputState.data?.channels?.[testChannel - 1]
  const pipelinesQuery = useQuery({ queryKey: ['pipelines'], queryFn: () => api<any[]>('/api/pipelines'), enabled: true, refetchInterval: 5000 })
  const relatedPipelines = (pipelinesQuery.data || []).filter(item => item.source_node_id === node.id || item.destination_node_id === node.id)
  const deleteMutation = useMutation({ mutationFn: () => api<void>(`/api/nodes/${node.id}`, { method: 'DELETE' }), onSuccess: () => {
    for (const queryKey of [['nodes'], ['overview'], ['gateways'], ['pipelines'], ['polling', node.id], ['channels', node.id], ['measurements', node.id], ['history', node.id], ['outputs', node.id], ['logs']]) {
      queryClient.invalidateQueries({ queryKey })
    }
    onDeleted(node.name)
  }, onError: () => { queryClient.invalidateQueries({ queryKey: ['pipelines'] }) } })
  const gatewayName = gateways.data?.find(gateway => gateway.id === node.gateway_id)?.name || node.gateway_id || 'Unassigned'
  const channelNames = channels.data?.map(item => item.label).join(', ') || (node.node_type === 'ANALOG_INPUT' ? 'AI1–AI6' : 'AO1–AO6')
  const canDelete = pipelinesQuery.isSuccess && relatedPipelines.length === 0 && !deleteMutation.isPending
  if (confirmDelete) return <Modal title="Delete Node" onClose={() => { if (!deleteMutation.isPending) setConfirmDelete(false) }}>
    <div className="notice warning">This node will be removed from active monitoring. Its measurement history and audit records will be preserved. The physical device will not be reset.</div>
    <div className="health-list" style={{ marginTop: 12 }}>
      <HealthLine label="Node" value={node.name} />
      <HealthLine label="Model" value={node.hardware_model} />
      <HealthLine label="Gateway" value={gatewayName} />
      <HealthLine label="Channels" value={channelNames} />
    </div>
    {node.node_type === 'ANALOG_OUTPUT' && <p className="error" style={{ marginTop: 12 }}>Deleting this node does not change the current analog output setpoints on the physical module.</p>}
    <div style={{ marginTop: 16 }}>
      <div className="panel-title">Pipeline dependencies</div>
      {pipelinesQuery.isLoading && <p className="panel-note">Checking all pipeline definitions…</p>}
      {pipelinesQuery.isError && <p className="error">Could not verify dependencies. {(pipelinesQuery.error as Error).message}</p>}
      {pipelinesQuery.isSuccess && relatedPipelines.length > 0 && <><p className="error">Remove these pipelines first, including disabled definitions.</p>{relatedPipelines.map(item => <div className="health-line" key={item.id}><span>{item.name}</span><span>{item.enabled ? 'Enabled' : 'Disabled'}{item.armed ? ' · Armed' : ''}</span></div>)}</>}
      {pipelinesQuery.isSuccess && relatedPipelines.length === 0 && <p className="panel-note">No dependent pipelines.</p>}
    </div>
    {deleteMutation.isError && <p className="error" role="alert">{(deleteMutation.error as Error).message}</p>}
    <div className="form-actions"><button className="button" disabled={deleteMutation.isPending} onClick={() => setConfirmDelete(false)}>Cancel</button><button className="button danger" disabled={!canDelete} onClick={() => deleteMutation.mutate()}><Trash2 size={14} />{deleteMutation.isPending ? 'Archiving…' : 'Delete Node'}</button></div>
  </Modal>
  return <Modal title={node.name} onClose={onClose}><div className="notice info">Persistent node identity <code>{node.id}</code> · {node.hardware_model} · {node.profile_id}</div><div className="health-list"><div className="health-line"><span>Gateway connection</span><Status good={node.gateway_connected}>{node.gateway_state || 'UNKNOWN'}</Status></div><div className="health-line"><span>Modbus health</span><Status good={node.modbus_healthy} warning={node.modbus_health !== 'RESPONDING' && node.gateway_connected}>{node.modbus_health || 'UNKNOWN'}</Status></div><div className="health-line"><span>{node.node_type === 'ANALOG_OUTPUT' ? 'Last verified device communication' : 'Last successful measurement'}</span><strong>{relativeTime(node.node_type === 'ANALOG_OUTPUT' ? node.last_modbus_at : node.last_measurement_at)}</strong></div></div><div className="form-grid" style={{ marginTop: 15 }}><Field label="Display name"><input className="input" value={name} onChange={e => setName(e.target.value)} /></Field><Field label="Assigned gateway"><select className="select" value={gatewayId} onChange={e => setGatewayId(e.target.value)}><option value="">Unassigned</option>{gateways.data?.filter(gateway => gateway.transport_mode === (node.node_type === 'ANALOG_INPUT' ? 'MODBUS_TCP' : 'TRANSPARENT_SERIAL')).map(gateway => <option value={gateway.id} key={gateway.id}>{gateway.name}</option>)}</select></Field><Field label="Modbus slave ID"><input className="input" type="number" min="1" max="247" value={slaveId} onChange={e => setSlaveId(e.target.value)} /></Field>{node.node_type === 'ANALOG_INPUT' && <Field label="Node polling"><select className="select" value={enabled ? 'enabled' : 'disabled'} onChange={e => setEnabled(e.target.value === 'enabled')}><option value="enabled">Enabled</option><option value="disabled">Disabled</option></select></Field>}</div><div style={{ marginTop: 18, borderTop: '1px solid var(--line)', paddingTop: 14 }}><div className="panel-title">ME31 channels · {channels.data?.length ?? '…'} configured</div>{channels.data?.map(item => <div className="health-line" key={item.id}><span>{item.label}</span><span>{item.enabled ? 'Enabled' : 'Disabled'}</span></div>)}</div>
    {node.node_type === 'ANALOG_OUTPUT' && <section style={{ marginTop: 18, borderTop: '1px solid var(--line)', paddingTop: 14 }}><div className="panel-title">Manual output test</div><p className="panel-note">Reads configured range and setpoint on open. No write occurs until you confirm the command.</p>{outputState.isError && <p className="error">{(outputState.error as Error).message}</p>}{outputState.data && <div className="channel-grid" style={{ margin: '10px 0' }}>{outputState.data.channels.map((item: any) => <div className="channel" key={item.channel}><div className="channel-head"><strong>AO{item.channel}</strong><span>{item.range_known ? `${item.output_min_ma}–${item.output_max_ma} mA` : 'Unknown range'}</span></div><div className="channel-value">{Number(item.setpoint_ma).toFixed(3)}</div><div className="channel-unit">Reported setpoint · last write {item.last_write?.result || 'none'}</div>{item.active_pipeline && <div className="secondary">Controlled by {item.active_pipeline.name}</div>}</div>)}</div>}<form onSubmit={e => { e.preventDefault(); if (!window.confirm(`Write ${targetMa} mA to AO${testChannel}? The ME31 may change a physical current output.`)) return; manualSet.mutate({ target_ma: Number(targetMa), confirm: true }) }}><div className="form-grid"><Field label="Output channel"><select className="select" value={testChannel} onChange={e => setTestChannel(Number(e.target.value))}>{Array.from({ length: 6 }, (_, i) => <option value={i + 1} key={i}>AO{i + 1}</option>)}</select></Field><Field label={`Target current (${testRange?.range_known ? `${testRange.output_min_ma}–${testRange.output_max_ma}` : 'range unknown'})`}><input className="input" type="number" min={testRange?.output_min_ma ?? 0} max={testRange?.output_max_ma ?? 20} step="0.01" value={targetMa} onChange={e => setTargetMa(e.target.value)} required /></Field></div><div className="form-actions"><button className="button primary" disabled={manualSet.isPending || !testRange?.range_known || !node.gateway_connected || !!testRange?.active_pipeline}>{manualSet.isPending ? 'Sending and reading back…' : testRange?.active_pipeline ? 'Pipeline owns this output' : 'Confirm and write output'}</button></div></form>{manualSet.isSuccess && <div className="notice info">AO{testChannel} acknowledged and read back at {Number((manualSet.data as any).acknowledged_ma).toFixed(3)} mA.</div>}{manualSet.isError && <p className="error">{(manualSet.error as Error).message}</p>}</section>}
    <div style={{ marginTop: 14 }}><div className="panel-title">Related pipelines</div>{relatedPipelines.length ? relatedPipelines.map(item => <div className="health-line" key={item.id}><span>{item.name}</span><span>{item.status}{item.armed ? ' · ARMED' : ''}</span></div>) : <p className="panel-note">No pipeline dependencies.</p>}</div><p className="panel-note" style={{ marginTop: 14 }}>{polling.data?.length ?? '…'} polling items · last input measurement {relativeTime(node.last_measurement_at)}</p><div className="form-actions"><button className="button danger" onClick={() => setConfirmDelete(true)}><Trash2 size={14} /> Delete Node</button><button className="button primary" onClick={() => mutation.mutate({ name, gateway_id: gatewayId || null, slave_id: Number(slaveId), polling_enabled: enabled })} disabled={mutation.isPending}>{mutation.isPending ? 'Saving…' : 'Save changes'}</button></div>{mutation.isError && <p className="error">{(mutation.error as Error).message}</p>}</Modal>
}

function Field({ label, children }: { label: string; children: ReactNode }) { return <div className="field"><label>{label}</label>{children}</div> }

function PollingPage() {
  const queryClient = useQueryClient()
  const [nodeType, setNodeType] = useState<Node['node_type']>('ANALOG_INPUT')
  const nodesQuery = useQuery({ queryKey: ['nodes', nodeType], queryFn: () => api<Node[]>(`/api/nodes?type=${nodeType}`) })
  const profileQuery = useQuery({ queryKey: ['profiles'], queryFn: () => api<{ id: string; registers: any[] }[]>('/api/device-profiles') })
  const nodes = nodesQuery.data || []
  const [nodeId, setNodeId] = useState('')
  const activeNode = nodes.find(node => node.id === nodeId) || nodes[0]
  const [openGroups, setOpenGroups] = useState<string[]>(['Analog Measurements'])
  useEffect(() => { setNodeId(''); setOpenGroups(nodeType === 'ANALOG_INPUT' ? ['Analog Measurements'] : ['Analog Output Measurements']) }, [nodeType])
  const pollingQuery = useQuery({ queryKey: ['polling', activeNode?.id], queryFn: () => api<PollItem[]>(`/api/nodes/${activeNode!.id}/polling`), enabled: !!activeNode, refetchInterval: 3000 })
  const outputChannelsQuery = useQuery({ queryKey: ['channels', activeNode?.id], queryFn: () => api<{ channel_index: number; enabled: number }[]>(`/api/nodes/${activeNode!.id}/channels`), enabled: !!activeNode && nodeType === 'ANALOG_OUTPUT' })
  const outputStateQuery = useQuery({ queryKey: ['outputs', activeNode?.id], queryFn: () => api<any>(`/api/nodes/${activeNode!.id}/outputs`), enabled: !!activeNode && nodeType === 'ANALOG_OUTPUT', refetchInterval: 5000, retry: false })
  const [rangeChannel, setRangeChannel] = useState<number | null>(null)
  const [requestedRange, setRequestedRange] = useState(0)
  const [confirmRange, setConfirmRange] = useState(false)
  const rangeMutation = useMutation({ mutationFn: ({ channel, range_code }: { channel: number; range_code: number }) => put(`/api/nodes/${activeNode!.id}/outputs/${channel}/range`, { range_code, confirm: true }), onSuccess: () => { queryClient.invalidateQueries({ queryKey: ['polling', activeNode?.id] }); queryClient.invalidateQueries({ queryKey: ['outputs', activeNode?.id] }); queryClient.invalidateQueries({ queryKey: ['overview'] }); setConfirmRange(false) } })
  const nodePollingMutation = useMutation({ mutationFn: (polling_enabled: boolean) => patch(`/api/nodes/${activeNode!.id}`, { polling_enabled }), onSuccess: () => { queryClient.invalidateQueries({ queryKey: ['nodes', nodeType] }); queryClient.invalidateQueries({ queryKey: ['polling', activeNode?.id] }); queryClient.invalidateQueries({ queryKey: ['overview'] }) } })
  const addMutation = useMutation({ mutationFn: (data: unknown) => post(`/api/nodes/${activeNode!.id}/polling`, data), onSuccess: () => queryClient.invalidateQueries({ queryKey: ['polling', activeNode?.id] }) })
  const toggleMutation = useMutation({ mutationFn: ({ id, enabled }: { id: string; enabled: boolean }) => patch(`/api/polling/${id}`, { enabled }), onSuccess: () => queryClient.invalidateQueries({ queryKey: ['polling', activeNode?.id] }) })
  const groupMutation = useMutation({ mutationFn: ({ group, enabled }: { group: string; enabled: boolean }) => put(`/api/nodes/${activeNode!.id}/polling/groups/${encodeURIComponent(group)}?enabled=${enabled}`, {}), onSuccess: () => queryClient.invalidateQueries({ queryKey: ['polling', activeNode?.id] }) })
  const onceMutation = useMutation({ mutationFn: (id: string) => post(`/api/polling/${id}/read`, {}), onSuccess: () => { queryClient.invalidateQueries({ queryKey: ['polling', activeNode?.id] }); queryClient.invalidateQueries({ queryKey: ['overview'] }) } })
  const deleteMutation = useMutation({ mutationFn: (id: string) => api(`/api/polling/${id}`, { method: 'DELETE' }), onSuccess: () => queryClient.invalidateQueries({ queryKey: ['polling', activeNode?.id] }) })
  const editMutation = useMutation({ mutationFn: ({ id, values }: { id: string; values: unknown }) => patch(`/api/polling/${id}`, values), onSuccess: () => { queryClient.invalidateQueries({ queryKey: ['polling', activeNode?.id] }); setEditItem(null) } })
  const nodeCategories = nodeType === 'ANALOG_INPUT' ? categories : ['Analog Output Measurements', 'Analog Output Configuration']
  const definitions = profileQuery.data?.filter(profile => profile.id === activeNode?.profile_id).flatMap(profile => profile.registers.filter(item => item.readable && item.quantity && (nodeType === 'ANALOG_INPUT' || (item.function_code === 3 && item.polling_safe))).map(item => ({ ...item, profile_id: profile.id }))) || []
  const available = definitions.filter(def => !pollingQuery.data?.some(item => item.register_name === def.name))
  const [editItem, setEditItem] = useState<PollItem | null>(null)
  const [floatItem, setFloatItem] = useState<PollItem | null>(null)
  const verifyFloatMutation = useMutation({ mutationFn: (values: { channel: number; reference_ma: number; tolerance_ma: number; byte_order: string; word_order: string }) => post<{ verified: boolean; observed_ma: number; reference_ma: number; tolerance_ma: number }>(`/api/polling/${floatItem!.id}/verify-float`, values), onSuccess: result => { queryClient.invalidateQueries({ queryKey: ['polling', activeNode?.id] }); if (result.verified) setFloatItem(null) } })
  const [customRegisterOpen, setCustomRegisterOpen] = useState(false)
  const setpointItem = pollingQuery.data?.find(item => item.register_name === 'AO setpoint readback')
  const rangeItem = pollingQuery.data?.find(item => item.register_name === 'AO output ranges')
  const setpointData = (() => { try { return JSON.parse(setpointItem?.last_value || 'null') as { raw_registers?: number[]; reported_setpoint_ma?: number[] } | null } catch { return null } })()
  const rangeData = (() => { try { return JSON.parse(rangeItem?.last_value || 'null') as { raw_registers?: number[]; output_ranges?: { raw_value: number; label: string; quality: string }[] } | null } catch { return null } })()
  const showValue = (item: PollItem) => {
    if (nodeType !== 'ANALOG_OUTPUT') return item.last_value ?? '-'
    try {
      const value = JSON.parse(item.last_value || 'null')
      if (value?.reported_setpoint_ma) return value.reported_setpoint_ma.map((ma: number) => `${ma.toFixed(3)} mA`).join(' · ')
      if (value?.output_ranges) return value.output_ranges.map((entry: { label: string; raw_value: number }) => `${entry.label} (${entry.raw_value})`).join(' · ')
    } catch { /* show stored value below */ }
    return item.last_value ?? '-'
  }
  return <>
    <PageHeading title="Modbus polling" description="Saved items are scheduled by the backend and serialized per gateway session." right={<span className="head-meta">Minimum interval 250 ms</span>} />
    <div className="toolbar"><Field label="Node type"><select className="select" value={nodeType} onChange={e => setNodeType(e.target.value as Node['node_type'])}><option value="ANALOG_INPUT">Analog Input</option><option value="ANALOG_OUTPUT">Analog Output</option></select></Field>{nodes.length > 0 && <Field label="Node"><select className="select" value={activeNode?.id || ''} onChange={e => setNodeId(e.target.value)}>{nodes.map(node => <option value={node.id} key={node.id}>{labelForNode(node)}</option>)}</select></Field>}{activeNode && <><span className="panel-note">Gateway {activeNode.gateway_id || 'unassigned'} · Slave {activeNode.slave_id} · {activeNode.node_type === 'ANALOG_OUTPUT' ? 'RTU-over-TCP' : 'Modbus TCP'} · {activeNode.polling_enabled ? 'Node polling enabled' : 'Node polling disabled'}</span><button className="button small" disabled={nodePollingMutation.isPending} onClick={() => nodePollingMutation.mutate(!activeNode.polling_enabled)}>{nodePollingMutation.isPending ? 'Saving…' : activeNode.polling_enabled ? 'Disable node polling' : 'Enable node polling'}</button></>}{nodePollingMutation.isError && <span className="error">{(nodePollingMutation.error as Error).message}</span>}</div>
    {nodes.length ? <>
      {nodeType === 'ANALOG_OUTPUT' && <><Panel title="Output channel readback" note="Reported setpoint is read from the ME31 register and does not represent an independently measured physical current."><div className="table-wrap"><table><thead><tr><th>Channel</th><th>Raw register</th><th>Reported Setpoint (mA)</th><th>Output range</th><th>Setpoint quality</th><th>Last setpoint read</th><th>Last range read</th><th>Action</th></tr></thead><tbody>{Array.from({ length: 6 }, (_, index) => {
        const setpointStatus = !setpointItem ? 'UNKNOWN' : !setpointItem.enabled ? 'DISABLED' : setpointItem.last_status
        const stale = !!setpointItem?.last_success_at && Date.now() - new Date(setpointItem.last_success_at).getTime() > Math.max(30000, setpointItem.interval_ms * 3)
        const rangeStale = !!rangeItem?.last_success_at && Date.now() - new Date(rangeItem.last_success_at).getTime() > Math.max(90000, rangeItem.interval_ms * 3)
        const channelConfig = outputChannelsQuery.data?.find(channel => channel.channel_index === index + 1)
        const channelEnabled = channelConfig?.enabled === 1
        const range = rangeData?.output_ranges?.[index]
        const point = setpointData?.reported_setpoint_ma?.[index]
        const quality = !channelConfig ? 'UNKNOWN' : !channelEnabled ? 'DISABLED' : stale ? 'STALE' : setpointStatus
        const rangeStatus = !rangeItem ? 'UNKNOWN' : !rangeItem.enabled ? 'DISABLED' : rangeStale ? 'STALE' : rangeItem.last_status
        return <tr key={index}><td>AO{index + 1}</td><td>{channelEnabled ? setpointData?.raw_registers?.[index] ?? '-' : '-'}</td><td>{!channelEnabled || point == null ? '-' : `${point.toFixed(3)} mA`}</td><td>{!channelConfig ? 'UNKNOWN' : !channelEnabled ? 'DISABLED' : `${range?.label || 'UNKNOWN'}${range ? ` (${range.raw_value})` : ''} · ${rangeStatus}`}</td><td><Status good={quality === 'GOOD'} warning={quality === 'STALE' || quality === 'TIMEOUT'}>{quality}</Status></td><td>{fmtTime(setpointItem?.last_success_at)}</td><td>{rangeItem?.last_success_at ? fmtTime(rangeItem.last_success_at) : 'No successful read'}</td><td><button className="button small" disabled={!channelEnabled || !activeNode?.polling_enabled || !activeNode?.gateway_connected || !!outputStateQuery.data?.channels?.[index]?.active_pipeline} onClick={() => { setRangeChannel(index + 1); setRequestedRange(range?.raw_value === 1 ? 0 : 1); setConfirmRange(false); rangeMutation.reset() }}>Configure range</button></td></tr>
      })}</tbody></table></div></Panel><div style={{ height: 12 }} /></>}
      {nodeCategories.map(category => {
        const items = (pollingQuery.data || []).filter(item => definitions.find(def => def.name === item.register_name)?.category === category || (!definitions.some(def => def.name === item.register_name) && category === 'Custom Registers'))
        const groupAvailable = available.filter(def => def.category === category)
        const isOpen = openGroups.includes(category)
        return <section className="panel" style={{ marginBottom: 12 }} key={category}>
          <div className="panel-head"><button className="nav-item" style={{ width: 'auto', margin: 0, padding: '7px 0', color: 'var(--ink)' }} onClick={() => setOpenGroups(isOpen ? openGroups.filter(x => x !== category) : [...openGroups, category])}>{isOpen ? <ChevronDown size={15} /> : <ChevronRight size={15} />}<span className="panel-title">{category}</span><span className="panel-note">{items.length} configured</span></button><div style={{ display: 'flex', alignItems: 'center', gap: 10 }}><button className="button small" onClick={() => groupMutation.mutate({ group: category, enabled: true })} disabled={!items.length || groupMutation.isPending}>Enable group</button><button className="button small" onClick={() => groupMutation.mutate({ group: category, enabled: false })} disabled={!items.length || groupMutation.isPending}>Disable group</button>{nodeType === 'ANALOG_INPUT' && category === 'Custom Registers' && <button className="button small" onClick={() => setCustomRegisterOpen(true)}><Plus size={13} /> Add custom</button>}{groupAvailable.length > 0 && <select className="select" style={{ width: 180, minHeight: 28, padding: '4px 7px' }} value="" aria-label={`Add ${category} polling item`} onChange={e => { const def = definitions.find(x => x.name === e.target.value); if (def) addMutation.mutate({ profile_id: def.profile_id, register_name: def.name, function_code: def.function_code, address: def.address, quantity: def.quantity, data_type: def.data_type, byte_order: def.byte_order || 'big', word_order: def.word_order || 'unverified', interval_ms: def.default_interval_ms || 1000, timeout_ms: 5000, retries: 1, scale: def.scale ?? 1, unit: def.unit || '', enabled: def.default_enabled !== false }) }}><option value="">Add profile item…</option>{groupAvailable.map(def => <option value={def.name} key={def.name}>{def.name} · 0x{def.address.toString(16).toUpperCase()}</option>)}</select>}</div></div>
          {isOpen && (items.length ? <div className="table-wrap"><table><thead><tr><th>Register</th><th>Function</th><th>Start</th><th>Quantity</th><th>Interval</th><th>Last value</th><th>Last response</th><th>Latency</th><th>State</th><th>Actions</th></tr></thead><tbody>{items.map(item => <tr key={item.id}><td><div className="primary-name">{item.register_name}</div><div className="secondary">{item.data_type} · {item.unit || 'raw'}{nodeType === 'ANALOG_OUTPUT' && <span> · Read only</span>}{item.data_type.startsWith('float') ? ` · ${item.float_verified ? `${item.byte_order}/${item.word_order}` : 'decoder unverified'}` : ''}</div></td><td>FC{String(item.function_code).padStart(2, '0')}</td><td>0x{item.address.toString(16).toUpperCase().padStart(4, '0')}</td><td>{item.quantity}</td><td>{item.interval_ms} ms</td><td>{showValue(item)}</td><td>{fmtTime(item.last_success_at)}</td><td>{item.last_latency_ms == null ? '-' : `${item.last_latency_ms.toFixed(1)} ms`}</td><td><Status good={item.last_status === 'GOOD' && (!item.data_type.startsWith('float') || !!item.float_verified)} warning={item.last_status === 'TIMEOUT'}>{item.enabled ? item.last_status : item.data_type.startsWith('float') && !item.float_verified ? 'VERIFY REQUIRED' : 'DISABLED'}</Status></td><td><div style={{ display: 'flex', gap: 5 }}><button className="button small" onClick={() => onceMutation.mutate(item.id)} disabled={onceMutation.isPending || !activeNode?.polling_enabled}>Read once</button>{item.data_type.startsWith('float') && !item.float_verified && <button className="button small" onClick={() => setFloatItem(item)} disabled={item.enabled !== 0}>Verify decoder</button>}<button className="button small" onClick={() => toggleMutation.mutate({ id: item.id, enabled: !item.enabled })} disabled={toggleMutation.isPending || (item.data_type.startsWith('float') && !item.float_verified)}>{item.enabled ? 'Disable' : 'Enable'}</button><button className="button small" onClick={() => setEditItem(item)}>Edit</button><button className="button small danger" onClick={() => deleteMutation.mutate(item.id)}>Remove</button></div></td></tr>)}</tbody></table></div> : <Empty title={pollingQuery.isLoading ? 'Loading polling configuration' : 'No items in this group'}>{groupAvailable.length ? 'Add a register from the selected device profile.' : 'No pollable profile items are available in this group.'}</Empty>)}
        </section>
      })}
      {(addMutation.isError || groupMutation.isError || onceMutation.isError || toggleMutation.isError || editMutation.isError || deleteMutation.isError) && <p className="error">{((addMutation.error || groupMutation.error || onceMutation.error || toggleMutation.error || editMutation.error || deleteMutation.error) as Error).message}</p>}
      {rangeChannel !== null && activeNode && <Modal title={`Configure AO${rangeChannel} output range`} onClose={() => { if (!rangeMutation.isPending) setRangeChannel(null) }}><div className="notice warning">Changing range may immediately affect the physical analog output current. This action changes device configuration only after explicit confirmation; it does not measure the physical current.</div><div className="health-list" style={{ marginTop: 12 }}><HealthLine label="Current hardware-reported range" value={rangeData?.output_ranges?.[rangeChannel - 1]?.label || 'UNKNOWN'} /><HealthLine label="Requested range" value={requestedRange === 0 ? '0–20 mA' : '4–20 mA'} /><HealthLine label="Reported setpoint" value={setpointData?.reported_setpoint_ma?.[rangeChannel - 1] == null ? 'UNKNOWN' : `${Number(setpointData.reported_setpoint_ma[rangeChannel - 1]).toFixed(3)} mA`} /><HealthLine label="Gateway / Modbus health" value={`${activeNode.gateway_state || 'UNKNOWN'} / ${activeNode.modbus_health || 'UNKNOWN'}`} /><HealthLine label="Pipeline ownership" value={outputStateQuery.data?.channels?.[rangeChannel - 1]?.active_pipeline?.name || 'No active pipeline owner'} /></div><div className="form-grid" style={{ marginTop: 14 }}><Field label="Output range"><select className="select" value={requestedRange} onChange={e => { setRequestedRange(Number(e.target.value)); setConfirmRange(false); rangeMutation.reset() }}><option value={0}>0–20 mA</option><option value={1}>4–20 mA</option></select></Field></div><label className="check-row" style={{ display: 'flex', alignItems: 'flex-start', gap: 8, marginTop: 14 }}><input type="checkbox" checked={confirmRange} onChange={e => setConfirmRange(e.target.checked)} /><span>I understand this may change the physical output. The reported setpoint is not a physical current measurement.</span></label>{rangeMutation.isError && <p className="error" role="alert">{(rangeMutation.error as Error).message}</p>}{rangeMutation.isSuccess && <div className="notice info">Range confirmed by FC03 readback: {(rangeMutation.data as { range_label?: string })?.range_label || (requestedRange === 0 ? '0–20 mA' : '4–20 mA')}. Reported setpoint does not verify physical current.</div>}<div className="form-actions"><button className="button" disabled={rangeMutation.isPending} onClick={() => setRangeChannel(null)}>Cancel</button><button className="button primary" disabled={!confirmRange || rangeMutation.isPending || !activeNode.gateway_connected || !!outputStateQuery.data?.channels?.[rangeChannel - 1]?.active_pipeline} onClick={() => rangeMutation.mutate({ channel: rangeChannel, range_code: requestedRange })}>{rangeMutation.isPending ? 'Writing and verifying…' : 'Confirm range change'}</button></div></Modal>}
      {customRegisterOpen && <Modal title="Add custom read register" onClose={() => setCustomRegisterOpen(false)}><p className="panel-note">Read-only custom polling item. Confirm the address and register format against the device documentation.</p><form onSubmit={e => { e.preventDefault(); const form = new FormData(e.currentTarget); addMutation.mutate({ register_name: String(form.get('register_name')), function_code: Number(form.get('function_code')), address: Number(form.get('address')), quantity: Number(form.get('quantity')), data_type: String(form.get('data_type')), byte_order: 'big', word_order: 'unverified', interval_ms: Number(form.get('interval_ms')), timeout_ms: 1500, retries: 1, scale: Number(form.get('scale')), unit: String(form.get('unit')), enabled: true }, { onSuccess: () => setCustomRegisterOpen(false) }) }}><div className="form-grid"><Field label="Register name"><input className="input" name="register_name" maxLength={120} required /></Field><Field label="Function code"><select className="select" name="function_code"><option value="3">FC03 · Holding registers</option><option value="4">FC04 · Input registers</option></select></Field><Field label="Start address"><input className="input" name="address" type="number" min="0" max="65535" defaultValue="0" required /></Field><Field label="Quantity"><input className="input" name="quantity" type="number" min="1" max="125" defaultValue="1" required /></Field><Field label="Data type"><select className="select" name="data_type"><option value="uint16">Unsigned 16-bit</option><option value="int16">Signed 16-bit</option><option value="uint16_array">Unsigned 16-bit array</option><option value="raw">Raw registers</option></select></Field><Field label="Poll interval (ms)"><input className="input" name="interval_ms" type="number" min="250" max="86400000" defaultValue="1000" required /></Field><Field label="Value scale"><input className="input" name="scale" type="number" step="any" defaultValue="1" required /></Field><Field label="Engineering unit"><input className="input" name="unit" maxLength={32} /></Field></div>{addMutation.isError && <p className="error">{(addMutation.error as Error).message}</p>}<div className="form-actions"><button type="button" className="button" onClick={() => setCustomRegisterOpen(false)}>Cancel</button><button className="button primary" disabled={addMutation.isPending}>Save polling item</button></div></form></Modal>}
      {editItem && <Modal title={`Edit ${editItem.register_name}`} onClose={() => setEditItem(null)}><form onSubmit={e => { e.preventDefault(); const form = new FormData(e.currentTarget); editMutation.mutate({ id: editItem.id, values: { interval_ms: Number(form.get('interval_ms')), timeout_ms: Number(form.get('timeout_ms')), retries: Number(form.get('retries')) } }) }}><div className="form-grid"><Field label="Interval (ms)"><input className="input" name="interval_ms" type="number" min="250" max="86400000" defaultValue={editItem.interval_ms} /></Field><Field label="Timeout (ms)"><input className="input" name="timeout_ms" type="number" min="100" max="60000" defaultValue={editItem.timeout_ms} /></Field><Field label="Retry count"><input className="input" name="retries" type="number" min="0" max="5" defaultValue={editItem.retries} /></Field></div>{editMutation.isError && <p className="error">{(editMutation.error as Error).message}</p>}<div className="form-actions"><button type="button" className="button" onClick={() => setEditItem(null)}>Cancel</button><button className="button primary" disabled={editMutation.isPending}>Save polling item</button></div></form></Modal>}
      {floatItem && <Modal title="Verify ME31 Float32 decoding" onClose={() => setFloatItem(null)}><p className="panel-note">Keep this item disabled. Compare one live channel with a trusted reference instrument, then choose byte and word order. The service does not guess the decoder.</p><form onSubmit={e => { e.preventDefault(); const form = new FormData(e.currentTarget); verifyFloatMutation.mutate({ channel: Number(form.get('channel')), reference_ma: Number(form.get('reference_ma')), tolerance_ma: Number(form.get('tolerance_ma')), byte_order: String(form.get('byte_order')), word_order: String(form.get('word_order')) }) }}><div className="form-grid"><Field label="Reference channel"><select className="select" name="channel">{Array.from({ length: 6 }, (_, index) => <option key={index + 1} value={index + 1}>AI{index + 1}</option>)}</select></Field><Field label="Known reference (mA)"><input className="input" name="reference_ma" type="number" step="any" min="0" max="30" required /></Field><Field label="Allowed difference (mA)"><input className="input" name="tolerance_ma" type="number" step="0.01" min="0.001" max="5" defaultValue="0.1" required /></Field><Field label="Byte order"><select className="select" name="byte_order"><option value="big">Big byte order</option><option value="little">Swapped bytes in each word</option></select></Field><Field label="Word order"><select className="select" name="word_order"><option value="BIG_WORD_FIRST">Big word first</option><option value="LITTLE_WORD_FIRST">Little word first</option></select></Field></div>{verifyFloatMutation.isError && <p className="error">{(verifyFloatMutation.error as Error).message}</p>}{verifyFloatMutation.data && !verifyFloatMutation.data.verified && <p className="error">Reference mismatch: decoded {verifyFloatMutation.data.observed_ma.toFixed(4)} mA; expected {verifyFloatMutation.data.reference_ma.toFixed(4)} ± {verifyFloatMutation.data.tolerance_ma.toFixed(4)} mA. Try another byte or word order.</p>}{verifyFloatMutation.data?.verified && <p className="notice info">Decoder matched the reference. Enable polling after reviewing the measured value.</p>}<div className="form-actions"><button type="button" className="button" onClick={() => setFloatItem(null)}>Cancel</button><button className="button primary" disabled={verifyFloatMutation.isPending}>Read and verify</button></div></form></Modal>}
    </> : <Empty title={`No ${nodeType === 'ANALOG_INPUT' ? 'input' : 'output'} nodes to poll`}>Register a node of this type and assign it to a gateway first.</Empty>}
  </>
}

function TelemetryPage() {
  const queryClient = useQueryClient()
  const nodesQuery = useQuery({ queryKey: ['nodes', 'ANALOG_INPUT'], queryFn: () => api<Node[]>('/api/nodes?type=ANALOG_INPUT') })
  const nodes = nodesQuery.data || []
  const [nodeId, setNodeId] = useState('')
  const [range, setRange] = useState('15m')
  const [paused, setPaused] = useState(false)
  const [socketState, setSocketState] = useState<'CONNECTING' | 'CONNECTED' | 'DISCONNECTED'>('DISCONNECTED')
  const activeNode = nodes.find(node => node.id === nodeId) || nodes[0]
  const since = useMemo(() => { const minutes = range === '1h' ? 60 : range === '6h' ? 360 : range === '24h' ? 1440 : 15; return new Date(Date.now() - minutes * 60000).toISOString() }, [range])
  const history = useQuery({ queryKey: ['history', activeNode?.id, range], queryFn: () => api<Measurement[]>(`/api/nodes/${activeNode!.id}/measurements/history?since=${encodeURIComponent(since)}&limit=5000`), enabled: !!activeNode, refetchInterval: paused ? false : 3000 })
  const latest = useQuery({ queryKey: ['measurements', activeNode?.id], queryFn: () => api<Measurement[]>(`/api/nodes/${activeNode!.id}/measurements/latest`), enabled: !!activeNode, refetchInterval: paused || socketState === 'CONNECTED' ? false : 2000 })
  const measurements = latest.data || []
  useEffect(() => {
    if (paused || !activeNode) { setSocketState('DISCONNECTED'); return }
    let socket: WebSocket | undefined
    let retryTimer: number | undefined
    let stableTimer: number | undefined
    let stopped = false
    let attempt = 0
    const connect = () => {
      if (stopped) return
      setSocketState('CONNECTING')
      const scheme = window.location.protocol === 'https:' ? 'wss:' : 'ws:'
      socket = new WebSocket(`${scheme}//${window.location.host}/ws/telemetry`)
      socket.onopen = () => socket?.send(JSON.stringify({ type: 'auth', token: getToken() }))
      socket.onmessage = event => {
        const message = JSON.parse(event.data)
        if (message.type === 'authenticated') { setSocketState('CONNECTED'); stableTimer = window.setTimeout(() => { attempt = 0 }, 60000) }
        if (message.type === 'telemetry' && Array.isArray(message.measurements)) {
          const rows = (message.measurements as Measurement[]).filter(row => row.node_id === activeNode.id)
          queryClient.setQueryData<Measurement[]>(['measurements', activeNode.id], current => {
            const byChannel = new Map((current || []).map(row => [row.channel, row]))
            rows.forEach(row => byChannel.set(row.channel, row))
            return [...byChannel.values()].sort((a, b) => a.channel - b.channel)
          })
        }
      }
      socket.onerror = () => socket?.close()
      socket.onclose = () => {
        if (stopped) return
        if (stableTimer) window.clearTimeout(stableTimer)
        setSocketState('DISCONNECTED')
        const delay = Math.min(30000, 1000 * 2 ** Math.min(attempt, 5))
        attempt += 1
        retryTimer = window.setTimeout(connect, delay)
      }
    }
    connect()
    return () => { stopped = true; if (retryTimer) window.clearTimeout(retryTimer); if (stableTimer) window.clearTimeout(stableTimer); socket?.close() }
  }, [activeNode?.id, paused, queryClient])
  function exportCsv() {
    const rows = history.data || []
    const csv = ['timestamp,channel,register_value,raw_ma,calibrated_ma,engineering_value,engineering_unit,quality', ...rows.map(row => [row.measured_at, row.channel, row.register_value, row.raw_ma, row.calibrated_ma, row.engineering_value ?? '', row.engineering_unit ?? '', row.quality].join(','))].join('\n')
    const link = document.createElement('a'); link.href = URL.createObjectURL(new Blob([csv], { type: 'text/csv' })); link.download = `${activeNode?.name || 'telemetry'}-${range}.csv`; link.click(); URL.revokeObjectURL(link.href)
  }
  return <>
    <PageHeading title="Live telemetry" description="Raw register, calibrated current and engineering value remain distinct." />
    {!nodes.length ? <Empty title="No input nodes registered">Live channels appear after a node has valid measurements.</Empty> : <>
      <div className="toolbar"><Field label="Input node"><select className="select" value={activeNode?.id || ''} onChange={e => setNodeId(e.target.value)}>{nodes.map(node => <option value={node.id} key={node.id}>{labelForNode(node)}</option>)}</select></Field><div className="field"><label>History window</label><div className="tabs">{[['15m','15 min'],['1h','1 hour'],['6h','6 hours'],['24h','24 hours']].map(([value,label]) => <button className={`tab ${range === value ? 'active' : ''}`} key={value} onClick={() => setRange(value)}>{label}</button>)}</div></div><Status good={socketState === 'CONNECTED'} warning={socketState === 'CONNECTING'}>{paused ? 'PAUSED' : `LIVE ${socketState.toLowerCase()}`}</Status><button className="button" style={{ marginTop: 18 }} onClick={() => setPaused(!paused)}>{paused ? 'Resume updates' : 'Pause updates'}</button><button className="button" style={{ marginTop: 18 }} onClick={exportCsv} disabled={!history.data?.length}><ArrowDownToLine size={14} /> Export CSV</button></div>
      {history.isError && <p className="error">{(history.error as Error).message}</p>}
      {measurements.length ? <div className="channel-grid">{Array.from({ length: 6 }, (_, index) => { const channel = index + 1; const measurement = measurements.find(row => row.channel === channel); const points = (history.data || []).filter(row => row.channel === channel).sort((a,b) => new Date(a.measured_at).getTime() - new Date(b.measured_at).getTime()); return <ChannelCard key={channel} channel={channel} measurement={measurement} points={points} pollingEnabled={!!activeNode?.polling_enabled} /> })}</div> : <Panel title="Channel values"><Empty title={latest.isLoading ? 'Waiting for measurement data' : 'No valid measurements yet'}>A TCP connection alone does not establish Modbus health. Check the communication log after the first poll.</Empty></Panel>}
    </>}
  </>
}

function ChannelCard({ channel, measurement, points, pollingEnabled }: { channel: number; measurement?: Measurement; points: Measurement[]; pollingEnabled: boolean }) {
  const good = measurement?.quality === 'GOOD'
  return <section className="channel"><div className="channel-head"><span>AI{channel}</span><Status good={good} warning={measurement?.quality === 'STALE'}>{measurement?.quality || 'UNKNOWN'}</Status></div>{measurement?.engineering_value != null ? <><div className="channel-value">{measurement.engineering_value.toFixed(2)}</div><div className="channel-unit">{measurement.engineering_unit || 'Engineering value'}</div></> : <><div className="channel-value">{measurement?.calibrated_ma.toFixed(3) ?? '-'}</div><div className="channel-unit">mA calibrated</div></>}<Trend points={points} /><div className="channel-meta"><span>Raw {measurement?.raw_ma.toFixed(3) ?? '-'} mA</span><span>Reg {measurement?.register_value ?? '-'}</span><span>Updated {relativeTime(measurement?.measured_at)}</span><span>{pollingEnabled ? 'Polling on' : 'Polling off'}</span></div></section>
}

function Trend({ points }: { points: Measurement[] }) {
  if (points.length < 2) return <svg className="trend" viewBox="0 0 120 30" role="img" aria-label="Not enough history to plot"><path d="M0 26 H120" stroke="var(--line)" strokeWidth="1" /></svg>
  const values = points.map(point => point.calibrated_ma); const min = Math.min(...values); const max = Math.max(...values); const span = max - min || 1
  const first = new Date(points[0].measured_at).getTime(); const last = new Date(points[points.length - 1].measured_at).getTime(); const duration = last - first || 1
  let path = ''
  points.forEach((point, index) => { const x = ((new Date(point.measured_at).getTime() - first) / duration) * 120; const y = 27 - ((point.calibrated_ma - min) / span) * 23; const gap = index > 0 && new Date(point.measured_at).getTime() - new Date(points[index - 1].measured_at).getTime() > 90000; path += `${index === 0 || gap ? 'M' : 'L'}${x.toFixed(1)},${y.toFixed(1)} ` })
  return <svg className="trend" viewBox="0 0 120 30" role="img" aria-label={`${points.length} real measurements over selected period`}><path d={path} fill="none" stroke="var(--accent)" strokeWidth="1.8" vectorEffect="non-scaling-stroke" /></svg>
}

function CalibrationPage() {
  const queryClient = useQueryClient()
  const nodesQuery = useQuery({ queryKey: ['nodes', 'ANALOG_INPUT'], queryFn: () => api<Node[]>('/api/nodes?type=ANALOG_INPUT') })
  const nodes = nodesQuery.data || []
  const [nodeId, setNodeId] = useState('')
  const [channel, setChannel] = useState(1)
  const [method, setMethod] = useState<'GAIN_OFFSET' | 'TWO_POINT'>('GAIN_OFFSET')
  const [gain, setGain] = useState('1')
  const [offset, setOffset] = useState('0')
  const [raw1, setRaw1] = useState('4')
  const [ref1, setRef1] = useState('4')
  const [raw2, setRaw2] = useState('20')
  const [ref2, setRef2] = useState('20')
  const [scaleEnabled, setScaleEnabled] = useState(false)
  const [inputMin, setInputMin] = useState('4')
  const [inputMax, setInputMax] = useState('20')
  const [engineeringMin, setEngineeringMin] = useState('0')
  const [engineeringMax, setEngineeringMax] = useState('100')
  const [unit, setUnit] = useState('bar')
  const activeNode = nodes.find(node => node.id === nodeId) || nodes[0]
  const latestQuery = useQuery({ queryKey: ['measurements', activeNode?.id], queryFn: () => api<Measurement[]>(`/api/nodes/${activeNode!.id}/measurements/latest`), enabled: !!activeNode, refetchInterval: 2000 })
  const calibrationQuery = useQuery({ queryKey: ['calibrations', activeNode?.id], queryFn: () => api<any[]>(`/api/nodes/${activeNode!.id}/calibration?channel=${channel}`), enabled: !!activeNode })
  const measurement = latestQuery.data?.find(item => item.channel === channel)
  const calibration = calibrationQuery.data?.[0]
  useEffect(() => { if (calibration) { setGain(String(calibration.gain)); setOffset(String(calibration.offset_ma)); setScaleEnabled(!!calibration.scaling_json); if (calibration.scaling_json) { const config = JSON.parse(calibration.scaling_json); setInputMin(String(config.input_min_ma)); setInputMax(String(config.input_max_ma)); setEngineeringMin(String(config.engineering_min)); setEngineeringMax(String(config.engineering_max)); setUnit(config.unit) } } else { setGain('1'); setOffset('0'); setScaleEnabled(false) } }, [calibration?.revision, channel])
  const scaling = scaleEnabled ? { input_min_ma: Number(inputMin), input_max_ma: Number(inputMax), engineering_min: Number(engineeringMin), engineering_max: Number(engineeringMax), unit, enabled: true } : null
  const preview = useMutation({ mutationFn: (values: { gain: number; offset_ma: number }) => post<{ calibrated_ma: number; engineering_value: number | null }>('/api/calibration/preview', { raw_ma: measurement?.raw_ma ?? 0, ...values, enabled: true, scaling }) })
  const capture = useMutation({ mutationFn: () => post<{ raw_ma: number; spread_ma: number; samples: number }>(`/api/nodes/${activeNode!.id}/calibration/${channel}/capture`, { tolerance_ma: 0.05 }), onSuccess: (result) => { if (captureTarget.current === 1) setRaw1(result.raw_ma.toFixed(4)); else setRaw2(result.raw_ma.toFixed(4)) } })
  const captureTarget = useRef<1 | 2>(1)
  const save = useMutation({ mutationFn: async () => {
    if (method === 'TWO_POINT') return post(`/api/nodes/${activeNode!.id}/calibration/two-point`, { channel, raw1: Number(raw1), reference1: Number(ref1), raw2: Number(raw2), reference2: Number(ref2), scaling })
    return put(`/api/nodes/${activeNode!.id}/calibration`, { channel, gain: Number(gain), offset_ma: Number(offset), enabled: true, method, scaling })
  }, onSuccess: () => { queryClient.invalidateQueries({ queryKey: ['calibrations', activeNode?.id] }); queryClient.invalidateQueries({ queryKey: ['measurements', activeNode?.id] }) } })
  const reset = useMutation({ mutationFn: () => put(`/api/nodes/${activeNode!.id}/calibration`, { channel, gain: 1, offset_ma: 0, enabled: false, method: 'RESET', scaling: null }), onSuccess: () => queryClient.invalidateQueries({ queryKey: ['calibrations', activeNode?.id] }) })
  const revert = useMutation({ mutationFn: (revision: number) => post(`/api/nodes/${activeNode!.id}/calibration/${channel}/revert/${revision}`, {}), onSuccess: () => queryClient.invalidateQueries({ queryKey: ['calibrations', activeNode?.id] }) })
  const calibrationHistory = calibrationQuery.data || []
  return <>
    <PageHeading title="Channel calibration" description="Software correction is stored separately from raw register values." />
    {!nodes.length ? <Empty title="No input nodes registered">Add an input device before setting channel calibration.</Empty> : <>
      <div className="toolbar"><Field label="Input node"><select className="select" value={activeNode?.id || ''} onChange={e => setNodeId(e.target.value)}>{nodes.map(node => <option value={node.id} key={node.id}>{labelForNode(node)}</option>)}</select></Field><Field label="Channel"><select className="select" value={channel} onChange={e => setChannel(Number(e.target.value))}>{Array.from({ length: 6 }, (_, i) => <option value={i + 1} key={i}>AI{i + 1}</option>)}</select></Field><Field label="Method"><select className="select" value={method} onChange={e => setMethod(e.target.value as any)}><option value="GAIN_OFFSET">Gain and offset</option><option value="TWO_POINT">Two-point calibration</option></select></Field></div>
      <div className="split-grid">
        <Panel title={`AI${channel} correction`} note="Preview values are not applied until saved."><div className="panel-body">
          <div className="notice info">Latest raw: <strong>{measurement ? `${measurement.raw_ma.toFixed(3)} mA` : 'No valid measurement'}</strong> · calibrated {measurement ? `${measurement.calibrated_ma.toFixed(3)} mA` : '-'}{measurement?.engineering_value != null ? ` · engineering ${measurement.engineering_value.toFixed(3)} ${measurement.engineering_unit || ''}` : ''} · quality {measurement?.quality || 'UNKNOWN'} · {relativeTime(measurement?.measured_at)}</div>
          {method === 'GAIN_OFFSET' ? <div className="form-grid"><Field label="Gain"><input className="input" type="number" min="0.0001" max="10" step="0.0001" value={gain} onChange={e => setGain(e.target.value)} /></Field><Field label="Offset (mA)"><input className="input" type="number" min="-25" max="25" step="0.001" value={offset} onChange={e => setOffset(e.target.value)} /></Field></div> : <div><div className="form-grid"><Field label="Raw point 1 (mA)"><input className="input" type="number" step="0.001" value={raw1} onChange={e => setRaw1(e.target.value)} /><button className="button small" type="button" onClick={() => { captureTarget.current = 1; capture.mutate() }} disabled={capture.isPending || measurement?.quality !== 'GOOD'}>Capture stable AI{channel}</button></Field><Field label="Reference 1 (mA)"><input className="input" type="number" step="0.001" value={ref1} onChange={e => setRef1(e.target.value)} /></Field><Field label="Raw point 2 (mA)"><input className="input" type="number" step="0.001" value={raw2} onChange={e => setRaw2(e.target.value)} /><button className="button small" type="button" onClick={() => { captureTarget.current = 2; capture.mutate() }} disabled={capture.isPending || measurement?.quality !== 'GOOD'}>Capture stable AI{channel}</button></Field><Field label="Reference 2 (mA)"><input className="input" type="number" step="0.001" value={ref2} onChange={e => setRef2(e.target.value)} /></Field></div><p className="panel-note" style={{ marginTop: 12 }}>Capture uses the median of three recent good samples and rejects stale or unstable readings. Raw points must be separated by at least 0.1 mA.</p></div>}
          <div style={{ marginTop: 18, borderTop: '1px solid var(--line)', paddingTop: 15 }}><label style={{ display: 'flex', gap: 8, alignItems: 'center', fontSize: 12, marginBottom: 12 }}><input type="checkbox" checked={scaleEnabled} onChange={e => setScaleEnabled(e.target.checked)} /> Enable engineering scaling</label>{scaleEnabled && <div className="form-grid"><Field label="Input minimum mA"><input className="input" type="number" step="0.01" value={inputMin} onChange={e => setInputMin(e.target.value)} /></Field><Field label="Input maximum mA"><input className="input" type="number" step="0.01" value={inputMax} onChange={e => setInputMax(e.target.value)} /></Field><Field label="Engineering minimum"><input className="input" type="number" step="0.01" value={engineeringMin} onChange={e => setEngineeringMin(e.target.value)} /></Field><Field label="Engineering maximum"><input className="input" type="number" step="0.01" value={engineeringMax} onChange={e => setEngineeringMax(e.target.value)} /></Field><Field label="Unit"><input className="input" value={unit} onChange={e => setUnit(e.target.value)} /></Field></div>}</div>
          <div className="form-actions" style={{ justifyContent: 'space-between' }}><button className="button danger" onClick={() => reset.mutate()} disabled={reset.isPending}>Disable / reset</button><div style={{ display: 'flex', gap: 8 }}><button className="button" onClick={() => { if (method === 'TWO_POINT') { const delta = Number(raw2) - Number(raw1); const nextGain = (Number(ref2) - Number(ref1)) / delta; preview.mutate({ gain: nextGain, offset_ma: Number(ref1) - nextGain * Number(raw1) }) } else preview.mutate({ gain: Number(gain), offset_ma: Number(offset) }) }} disabled={preview.isPending || measurement?.quality !== 'GOOD' || (method === 'TWO_POINT' && Math.abs(Number(raw2) - Number(raw1)) < 0.1)}>Preview</button><button className="button primary" onClick={() => save.mutate()} disabled={save.isPending}>Apply calibration</button></div></div>
          {preview.data && <div className="notice info" style={{ marginTop: 12, marginBottom: 0 }}>Preview: {preview.data.calibrated_ma.toFixed(4)} mA{preview.data.engineering_value != null ? ` · ${preview.data.engineering_value.toFixed(3)} ${scaling?.unit || ''}` : ''}. Not saved.</div>}
          {save.isSuccess && <div className="notice info" style={{ marginTop: 12, marginBottom: 0 }}>Calibration saved{(save.data as { revision?: number } | undefined)?.revision ? ` as revision r${(save.data as { revision: number }).revision}` : ''}. Raw readings remain unchanged.</div>}
          {(save.isError || preview.isError || reset.isError || capture.isError) && <p className="error">{((save.error || preview.error || reset.error || capture.error) as Error).message}</p>}
        </div></Panel>
        <Panel title="Applied configuration" note="Revisions are append-only; reverting creates a new revision."><div className="panel-body health-list"><HealthLine label="Calibration state" value={calibration?.enabled ? 'Enabled' : 'Disabled'} good={!!calibration?.enabled} /><HealthLine label="Gain" value={calibration ? Number(calibration.gain).toFixed(5) : '1.00000'} /><HealthLine label="Offset" value={calibration ? `${Number(calibration.offset_ma).toFixed(4)} mA` : '0.0000 mA'} /><HealthLine label="Revision" value={calibration?.revision ? `r${calibration.revision}` : 'Default'} /><HealthLine label="Modified" value={fmtTime(calibration?.created_at)} /><HealthLine label="Modified by" value={calibration?.modified_by || 'Default configuration'} /><div style={{ paddingTop: 14, fontSize: 11, color: 'var(--muted)' }}>Calibration modifies the reported mA value in software. It does not write a hardware calibration register.</div></div></Panel>
      </div>
      <div style={{ marginTop: 18 }}><Panel title="Calibration history" note="Select a previous revision to restore its values as a new revision.">{calibrationHistory.length ? <div className="table-wrap"><table><thead><tr><th>Revision</th><th>Method</th><th>Gain</th><th>Offset</th><th>State</th><th>Modified</th><th>Action</th></tr></thead><tbody>{calibrationHistory.map(entry => <tr key={entry.revision}><td>r{entry.revision}</td><td>{entry.method}</td><td>{Number(entry.gain).toFixed(5)}</td><td>{Number(entry.offset_ma).toFixed(4)} mA</td><td>{entry.enabled ? 'Enabled' : 'Disabled'}</td><td>{fmtTime(entry.created_at)}</td><td><button className="button small" onClick={() => revert.mutate(entry.revision)} disabled={revert.isPending}>Revert to this</button></td></tr>)}</tbody></table></div> : <Empty title="No calibration revisions">Default gain 1 and offset 0 are active until a configuration is saved.</Empty>}</Panel></div>
    </>}
  </>
}

function LogsPage() {
  const [page, setPage] = useState(0)
  const [result, setResult] = useState('')
  const [selected, setSelected] = useState<EventRow | null>(null)
  const query = useQuery({ queryKey: ['logs', page, result], queryFn: () => api<EventRow[]>(`/api/logs?limit=50&offset=${page * 50}${result ? `&result=${encodeURIComponent(result)}` : ''}`), refetchInterval: 5000 })
  return <><PageHeading title="Communication logs" description="Validated request and response frames are retained for protocol diagnosis." /><div className="toolbar"><Field label="Result filter"><select className="select" value={result} onChange={e => { setResult(e.target.value); setPage(0) }}><option value="">All results</option>{['SUCCESS','TIMEOUT','MODBUS_ERROR','INVALID_RESPONSE','DISCONNECTED','CONNECTED','PENDING'].map(value => <option key={value}>{value}</option>)}</select></Field><span className="panel-note">50 events per page</span></div><Panel title="Event stream" action={<div style={{ display: 'flex', gap: 7 }}><button className="button small" onClick={() => setPage(Math.max(0,page-1))} disabled={page===0}>Previous</button><button className="button small" onClick={() => setPage(page+1)} disabled={(query.data?.length || 0) < 50}>Next</button></div>}>{query.data?.length ? <div className="table-wrap"><table><thead><tr><th>Timestamp</th><th>Gateway</th><th>Node</th><th>Direction</th><th>Protocol</th><th>Function</th><th>Address / count</th><th>Latency</th><th>Result</th></tr></thead><tbody>{query.data.map(row => <tr key={row.id} data-clickable="true" onClick={() => setSelected(row)}><td>{fmtTime(row.at)}</td><td>{row.gateway_id?.slice(0,8) || '-'}</td><td>{row.node_id?.slice(0,8) || '-'}</td><td>{row.direction || '-'}</td><td>{row.protocol || '-'}</td><td>{row.function_code ? `FC${row.function_code}` : '-'}</td><td>{row.address == null ? '-' : `0x${row.address.toString(16).toUpperCase()} / ${row.quantity}`}</td><td>{row.latency_ms == null ? '-' : `${row.latency_ms.toFixed(1)} ms`}</td><td><Status good={row.result === 'SUCCESS' || row.result === 'CONNECTED'} warning={row.result === 'PENDING'}>{row.result}</Status></td></tr>)}</tbody></table></div> : <Empty title={query.isLoading ? 'Loading event log' : 'No events match this filter'}>Gateway activity and Modbus polling results appear here.</Empty>}</Panel>{selected && <Modal title="Communication frame inspector" onClose={() => setSelected(null)}><div className="health-list"><HealthLine label="Timestamp" value={fmtTime(selected.at)} /><HealthLine label="Result" value={selected.result} /><HealthLine label="Protocol" value={selected.protocol || '-'} /><HealthLine label="Function" value={selected.function_code ? `FC${selected.function_code}` : '-'} /><HealthLine label="Register range" value={selected.address == null ? '-' : `0x${selected.address.toString(16).toUpperCase()} · ${selected.quantity} registers`} /><HealthLine label="Round trip" value={selected.latency_ms == null ? '-' : `${selected.latency_ms.toFixed(1)} ms`} /></div><p>{selected.detail}</p><div className="field"><label>Request HEX</label><pre className="hex">{selected.request_hex || 'No frame captured for this event.'}</pre></div><div className="field" style={{ marginTop: 12 }}><label>Response HEX</label><pre className="hex">{selected.response_hex || 'No frame captured for this event.'}</pre></div></Modal>}</>
}

function SettingsPage({ theme, setTheme }: { theme: string; setTheme: (value: string) => void }) {
  const settings = useQuery({ queryKey: ['settings'], queryFn: () => api<any>('/api/settings') })
  const gateways = useQuery({ queryKey: ['gateways'], queryFn: () => api<Gateway[]>('/api/gateways') })
  const sessions = useQuery({ queryKey: ['sessions'], queryFn: () => api<any[]>('/api/gateways/sessions'), refetchInterval: 3000 })
  const nodes = useQuery({ queryKey: ['nodes'], queryFn: () => api<Node[]>('/api/nodes') })
  const pipelines = useQuery({ queryKey: ['pipelines'], queryFn: () => api<any[]>('/api/pipelines') })
  const [showGateway, setShowGateway] = useState(false)
  const [editGateway, setEditGateway] = useState<Gateway | null>(null)
  const [deleteGateway, setDeleteGateway] = useState<Gateway | null>(null)
  const [reconnectGateway, setReconnectGateway] = useState<Gateway | null>(null)
  const [ingressPort, setIngressPort] = useState('')
  const [ingressPeer, setIngressPeer] = useState('')
  const [editName, setEditName] = useState('')
  const [editModel, setEditModel] = useState('')
  const [editTransport, setEditTransport] = useState('MODBUS_TCP')
  const [actionFeedback, setActionFeedback] = useState('')
  const [outputTimeouts, setOutputTimeouts] = useState({ output_range_timeout_ms: 5000, output_write_timeout_ms: 5000, output_readback_timeout_ms: 5000 })
  const [registrationPacket, setRegistrationPacket] = useState<{ gateway_id: string; registration_packet: string; configuration_commands: string[] } | null>(null)
  const [copiedRegistration, setCopiedRegistration] = useState(false)
  const queryClient = useQueryClient()
  useEffect(() => { if (settings.data?.output_timeouts) setOutputTimeouts({ output_range_timeout_ms: settings.data.output_timeouts.range_ms, output_write_timeout_ms: settings.data.output_timeouts.write_ms, output_readback_timeout_ms: settings.data.output_timeouts.readback_ms }) }, [settings.data])
  const invalidateGateway = () => { queryClient.invalidateQueries({ queryKey: ['gateways'] }); queryClient.invalidateQueries({ queryKey: ['sessions'] }); queryClient.invalidateQueries({ queryKey: ['nodes'] }); queryClient.invalidateQueries({ queryKey: ['overview'] }); queryClient.invalidateQueries({ queryKey: ['pipelines'] }) }
  const mutation = useMutation({ mutationFn: (data: unknown) => post('/api/gateways', data), onSuccess: () => { invalidateGateway(); setShowGateway(false); setActionFeedback('Gateway registered.') } })
  const commission = useMutation({ mutationFn: ({ session_id, gateway_id }: any) => post(`/api/gateways/sessions/${session_id}/assign/${gateway_id}`, {}), onSuccess: () => { invalidateGateway(); setActionFeedback('Pending session assigned successfully.') } })
  const updateGateway = useMutation({ mutationFn: (data: unknown) => patch(`/api/gateways/${editGateway?.id}`, data), onSuccess: () => { invalidateGateway(); setEditGateway(null); setActionFeedback('Gateway configuration saved.') } })
  const disconnect = useMutation({ mutationFn: (gatewayId: string) => post(`/api/gateways/${gatewayId}/disconnect`, {}), onSuccess: () => { invalidateGateway(); setActionFeedback('Gateway session disconnected.') } })
  const removeGateway = useMutation({ mutationFn: (gatewayId: string) => api<void>(`/api/gateways/${gatewayId}`, { method: 'DELETE' }), onSuccess: () => { invalidateGateway(); setDeleteGateway(null); setActionFeedback('Gateway deleted and registration credentials revoked.') } })
  const registration = useMutation({ mutationFn: (gatewayId: string) => post<{ gateway_id: string; registration_packet: string; configuration_commands: string[] }>(`/api/gateways/${gatewayId}/registration-token`, {}), onSuccess: data => { setRegistrationPacket(data); setCopiedRegistration(false) } })
  const trustedIngress = useMutation({ mutationFn: ({ gateway, enabled }: { gateway: Gateway; enabled: boolean }) => put(`/api/gateways/${gateway.id}/trusted-ingress`, enabled ? { enabled: true, ingress_id: `${gateway.id}-wg`, listener_port: Number(ingressPort), trusted_peer_ip: ingressPeer } : { enabled: false }), onSuccess: (_result, variables) => { invalidateGateway(); setReconnectGateway(null); setActionFeedback(variables.enabled ? 'Authenticated VPN ingress provisioned; reconnects on this binding are commissioned automatically.' : 'Automatic commissioning suspended. Existing device registration is preserved.') } })
  const saveTimeouts = useMutation({ mutationFn: () => put('/api/settings/output-timeouts', outputTimeouts), onSuccess: () => { queryClient.invalidateQueries({ queryKey: ['settings'] }); setActionFeedback('Output communication timeouts saved.') } })
  return <><PageHeading title="Settings" description="Service defaults and gateway commissioning state." right={<button className="button primary" onClick={() => setShowGateway(true)}><Plus size={14} /> Register gateway</button>} /><div className="split-grid"><Panel title="Service configuration" note="Read from the running backend"><div className="panel-body health-list"><HealthLine label="TCP listener" value={`${settings.data?.tcp_listener.host || '-'}:${settings.data?.tcp_listener.port || '-'}`} /><HealthLine label="Trusted VPN ingress" value={settings.data?.trusted_ingress?.enabled ? `${settings.data.trusted_ingress.interface} · ${settings.data.trusted_ingress.host} · ${settings.data.trusted_ingress.active_listeners} active` : 'Not configured'} /><HealthLine label="Read-only gateway checks" value={settings.data?.gateway_healthcheck?.enabled ? `${settings.data.gateway_healthcheck.interval_seconds}s · timeout ${settings.data.gateway_healthcheck.timeout_ms}ms · ${settings.data.gateway_healthcheck.failure_threshold} failures` : 'Disabled'} /><HealthLine label="Minimum poll interval" value={`${settings.data?.polling.minimum_interval_ms ?? '-'} ms`} /><HealthLine label="Default timeout" value={`${settings.data?.polling.default_timeout_ms ?? '-'} ms`} /><HealthLine label="Freshness threshold" value={`${settings.data?.freshness_seconds ?? '-'} seconds`} /><HealthLine label="Hardware writes" value={settings.data?.hardware_writes || 'Loading'} /></div></Panel><Panel title="Appearance" note="Stored in this browser"><div className="panel-body"><div className="field"><label htmlFor="theme">Color theme</label><select id="theme" className="select" value={theme} onChange={e => setTheme(e.target.value)}><option value="light">Light</option><option value="dark">Dark</option></select></div></div></Panel></div>
    <div style={{ marginTop: 18 }}><Panel title="Output communication timeouts" note="Persistent backend limits for range reads, FC16 acknowledgements and setpoint readback. Values are bounded to 250–30000 ms."><div className="panel-body"><div className="form-grid"><Field label="Range read timeout (ms)"><input className="input" type="number" min={250} max={30000} value={outputTimeouts.output_range_timeout_ms} onChange={e => setOutputTimeouts(old => ({ ...old, output_range_timeout_ms: Number(e.target.value) }))} /></Field><Field label="FC16 acknowledgement timeout (ms)"><input className="input" type="number" min={250} max={30000} value={outputTimeouts.output_write_timeout_ms} onChange={e => setOutputTimeouts(old => ({ ...old, output_write_timeout_ms: Number(e.target.value) }))} /></Field><Field label="Setpoint readback timeout (ms)"><input className="input" type="number" min={250} max={30000} value={outputTimeouts.output_readback_timeout_ms} onChange={e => setOutputTimeouts(old => ({ ...old, output_readback_timeout_ms: Number(e.target.value) }))} /></Field></div><div className="form-actions"><button className="button primary" disabled={saveTimeouts.isPending} onClick={() => saveTimeouts.mutate()}>{saveTimeouts.isPending ? "Saving…" : "Save timeouts"}</button></div>{saveTimeouts.isError && <p className="error" role="alert">{(saveTimeouts.error as Error).message}</p>}</div></Panel></div>
    <div style={{ marginTop: 18 }}><Panel title="Gateway registry" note="A TCP socket is not assigned to a gateway until commissioned.">{gateways.data?.length ? <div className="table-wrap"><table><thead><tr><th>Name</th><th>Model</th><th>Transport framing</th><th>Gateway state</th><th>Reconnect / Modbus</th><th>Connection history</th><th>Last diagnostic</th><th>Actions</th></tr></thead><tbody>{gateways.data.map(gateway => {
      const session = sessions.data?.find(item => item.gateway_id === gateway.id)
      const associatedNodes = (nodes.data || []).filter(node => node.gateway_id === gateway.id)
      const associatedPipelines = (pipelines.data || []).filter(item => associatedNodes.some(node => node.id === item.source_node_id || node.id === item.destination_node_id))
      return <tr key={gateway.id}><td><div className="primary-name">{gateway.name}</div><div className="secondary">{gateway.id}</div></td><td>{gateway.model || '-'}</td><td>{gateway.transport_mode}</td><td><Status good={gateway.connection_state === 'CONNECTED'}>{gateway.connection_state || (session ? 'CONNECTED' : 'DISCONNECTED')}</Status><div className="secondary">Identity {gateway.identity_state || 'NOT_VERIFIED'} · {gateway.commissioning_state || 'UNKNOWN'}</div><div className="secondary">{gateway.manual_intervention_required ? 'Manual commissioning required' : gateway.commissioning_method || 'Commissioned'}</div><div className="secondary">Modbus {gateway.gateway_modbus_state || 'UNKNOWN'} · generation {gateway.session_generation ?? 0}</div></td><td>{gateway.reconnection_count ?? 0} reconnects<div className="secondary">Last valid Modbus {relativeTime(gateway.last_successful_modbus_at)}</div><div className="secondary">{gateway.last_modbus_transaction ? `${gateway.last_modbus_transaction.result} · FC${gateway.last_modbus_transaction.function_code} · ${relativeTime(gateway.last_modbus_transaction.at)}` : 'No Modbus transaction'}</div></td><td><div>Activity {relativeTime(gateway.last_activity_at)}</div><div className="secondary">Connected {relativeTime(gateway.last_connected_at)} · reconnected {relativeTime(gateway.last_reconnected_at)} · disconnected {relativeTime(gateway.last_disconnected_at)}</div><div className="secondary" title={gateway.last_disconnect_reason || ''}>Reason: {gateway.last_disconnect_reason || '—'}</div></td><td>{gateway.last_diagnostic ? <><Status good={gateway.last_diagnostic.result === 'OK'}>{gateway.last_diagnostic.result}</Status><div className="secondary" title={gateway.last_diagnostic.detail}>{gateway.last_diagnostic.detail || relativeTime(gateway.last_diagnostic.at)}</div></> : <span className="secondary">No diagnostic events</span>}</td><td><div className="action-row">
        {!session && sessions.data?.some(item => !item.gateway_id) && <select className="select" style={{ minWidth: 190 }} defaultValue="" disabled={commission.isPending} onChange={e => { if (e.target.value) { setActionFeedback(''); commission.mutate({ session_id: e.target.value, gateway_id: gateway.id }) } }}><option value="">Assign pending session…</option>{sessions.data.filter(item => !item.gateway_id).map(item => <option key={item.session_id} value={item.session_id}>{item.peer} · {item.session_id.slice(0,8)}</option>)}</select>}
        {gateway.link_identity_available && <button className="button small" onClick={() => registration.mutate(gateway.id)} disabled={registration.isPending}>G781 LINK identity</button>}
        <details className="actions-menu"><summary className="button small">Actions</summary><div className="actions-menu-list"><button onClick={() => { setEditGateway(gateway); setEditName(gateway.name); setEditModel(gateway.model); setEditTransport(gateway.transport_mode); setActionFeedback('') }}>Edit gateway</button><button onClick={() => { setReconnectGateway(gateway); setIngressPort(String(gateway.listener_port || '')); setIngressPeer(gateway.trusted_peer_ip || '') }}>{gateway.auto_reconnect_enabled ? 'Manage secure reconnect' : 'Provision secure reconnect'}</button>{gateway.auto_reconnect_enabled ? <button disabled={trustedIngress.isPending} onClick={() => trustedIngress.mutate({ gateway, enabled: false })}>Suspend auto commissioning</button> : null}<button disabled={!session || disconnect.isPending} onClick={() => disconnect.mutate(gateway.id)}>Disconnect session</button><button className="danger-text" onClick={() => setDeleteGateway(gateway)}>Delete gateway</button></div></details>
      </div></td></tr>
    })}</tbody></table></div> : <Empty title="No gateways registered">Register each gateway using its verified transport framing.</Empty>}</Panel>
      {registration.isError && <p className="error" role="alert">{(registration.error as Error).message}</p>}
      {commission.isError && <p className="error" role="alert">Session assignment failed: {(commission.error as Error).message}</p>}
      {disconnect.isError && <p className="error" role="alert">Disconnect failed: {(disconnect.error as Error).message}</p>}
      {removeGateway.isError && <p className="error" role="alert">Gateway deletion failed: {(removeGateway.error as Error).message}</p>}
      {actionFeedback && <div className="notice info" role="status">{actionFeedback}</div>}
    </div>
    <div style={{ marginTop: 18 }}><Panel title="Unassigned TCP sessions" note="Peer addresses are shown only for operator commissioning.">{sessions.data?.filter(item => !item.gateway_id).length ? <div className="table-wrap"><table><thead><tr><th>Session</th><th>Peer address</th><th>State</th><th>First seen</th></tr></thead><tbody>{sessions.data.filter(item => !item.gateway_id).map(item => <tr key={item.session_id}><td>{item.session_id}</td><td>{item.peer}</td><td>Awaiting assignment</td><td>{relativeTime(item.last_activity ? new Date(item.last_activity * 1000).toISOString() : null)}</td></tr>)}</tbody></table></div> : <Empty title="No pending gateway connections">A connection appears after an LTE gateway opens the TCP listener.</Empty>}</Panel></div>
    {showGateway && <Modal title="Register gateway" onClose={() => setShowGateway(false)}><form onSubmit={e => { e.preventDefault(); const form = new FormData(e.currentTarget); mutation.mutate({ name: form.get('name'), model: form.get('model'), transport_mode: form.get('transport_mode') }) }}><div className="notice">Confirm the USR-G781 forwarding mode first. This setting determines whether the service sends MBAP frames or RTU frames.</div><div className="form-grid"><Field label="Gateway name"><input className="input" name="name" required /></Field><Field label="Gateway model"><input className="input" name="model" defaultValue="USR-G781" /></Field><Field label="Transport mode"><select className="select" name="transport_mode"><option value="TRANSPARENT_SERIAL">Transparent serial / RTU</option><option value="MODBUS_RTU">Modbus RTU</option><option value="MODBUS_TCP">Modbus TCP</option></select></Field></div>{mutation.isError && <p className="error">{(mutation.error as Error).message}</p>}<div className="form-actions"><button type="button" className="button" onClick={() => setShowGateway(false)}>Cancel</button><button className="button primary" disabled={mutation.isPending}>Save gateway</button></div></form></Modal>}
    {editGateway && <Modal title={`Edit ${editGateway.name}`} onClose={() => setEditGateway(null)}><form onSubmit={e => { e.preventDefault(); updateGateway.mutate({ name: editName, model: editModel, transport_mode: editTransport }) }}><div className="notice info">Changing framing requires a disconnected gateway and no assigned ME31 nodes that depend on the existing transport.</div><div className="form-grid"><Field label="Gateway name"><input className="input" value={editName} onChange={e => setEditName(e.target.value)} required maxLength={100} /></Field><Field label="Gateway model"><input className="input" value={editModel} onChange={e => setEditModel(e.target.value)} maxLength={100} /></Field><Field label="Transport framing"><select className="select" value={editTransport} onChange={e => setEditTransport(e.target.value)}><option value="MODBUS_TCP">Modbus TCP / MBAP</option><option value="TRANSPARENT_SERIAL">Transparent serial / RTU</option><option value="MODBUS_RTU">Modbus RTU</option></select></Field></div>{updateGateway.isError && <p className="error" role="alert">{(updateGateway.error as Error).message}</p>}<div className="form-actions"><button type="button" className="button" onClick={() => setEditGateway(null)}>Cancel</button><button className="button primary" disabled={updateGateway.isPending}>{updateGateway.isPending ? 'Saving…' : 'Save gateway'}</button></div></form></Modal>}
    {reconnectGateway && <Modal title={`Secure reconnect · ${reconnectGateway.name}`} onClose={() => { setReconnectGateway(null); trustedIngress.reset() }}><div className="notice info">The shared listener cannot identify these gateways safely. Automatic commissioning uses a dedicated port bound to the VPS WireGuard interface and an authenticated, unique WireGuard peer address. Configure the site router/tunnel first; do not expose this port publicly. This does not arm pipelines.</div><div className="form-grid" style={{ marginTop: 14 }}><Field label="Trusted ingress ID"><input className="input" value={`${reconnectGateway.id}-wg`} readOnly /></Field><Field label="Dedicated listener port"><input className="input" type="number" min={1024} max={65535} value={ingressPort} onChange={e => setIngressPort(e.target.value)} /></Field><Field label="WireGuard peer address"><input className="input" placeholder="10.70.0.11" value={ingressPeer} onChange={e => setIngressPeer(e.target.value)} /></Field></div><p className="panel-note">Transport remains {reconnectGateway.transport_mode}; no registration bytes are added to Modbus TCP or RTU traffic. Current binding: {reconnectGateway.trusted_ingress_id || 'none'} · {reconnectGateway.trusted_peer_ip || 'none'}:{reconnectGateway.listener_port || 'none'}.</p>{trustedIngress.isError && <p className="error" role="alert">{(trustedIngress.error as Error).message}</p>}<div className="form-actions"><button className="button" onClick={() => setReconnectGateway(null)}>Cancel</button><button className="button primary" disabled={trustedIngress.isPending || !ingressPort || !ingressPeer} onClick={() => trustedIngress.mutate({ gateway: reconnectGateway, enabled: true })}>{trustedIngress.isPending ? 'Provisioning…' : 'Enable secure reconnect'}</button></div></Modal>}
    {deleteGateway && (() => { const ownedNodes=(nodes.data||[]).filter(node=>node.gateway_id===deleteGateway.id); const dependent=(pipelines.data||[]).filter(item=>ownedNodes.some(node=>node.id===item.source_node_id||node.id===item.destination_node_id)); const blocked=ownedNodes.length>0||dependent.some(item=>item.enabled||item.armed); return <Modal title="Delete gateway" onClose={() => setDeleteGateway(null)}><div className="notice">Delete <strong>{deleteGateway.name}</strong> and revoke its gateway registration token? Communication history is retained.</div><div className="health-list"><div className="health-line"><span>Assigned nodes</span><strong>{ownedNodes.length ? ownedNodes.map(node=>node.name).join(', ') : 'None'}</strong></div><div className="health-line"><span>Related pipelines</span><strong>{dependent.length ? dependent.map(item=>`${item.name} (${item.status})`).join(', ') : 'None'}</strong></div></div>{blocked && <p className="error">Gateway has dependencies. Disable or delete affected pipelines, then reassign the listed nodes before deletion.</p>}{removeGateway.isError && <p className="error" role="alert">{(removeGateway.error as Error).message}</p>}<div className="form-actions"><button className="button" onClick={() => setDeleteGateway(null)}>Cancel</button><button className="button danger" disabled={blocked||removeGateway.isPending} onClick={() => removeGateway.mutate(deleteGateway.id)}>{removeGateway.isPending ? 'Deleting…' : 'Delete gateway'}</button></div></Modal> })()}
    {registrationPacket && <Modal title="USR-G781 reconnect identity" onClose={() => setRegistrationPacket(null)}><div className="notice">Use only with the G781 in network-transparent mode. Protect this registration token with TLS or a dedicated trusted VPN. Configure registration send mode as LINK so the packet is sent only when the TCP connection opens.</div><div className="field" style={{ marginTop: 14 }}><label>Configuration commands · secret shown once</label><pre className="hex">{registrationPacket.configuration_commands.join('\n')}</pre></div><div className="field" style={{ marginTop: 12 }}><label>Decoded registration packet</label><pre className="hex">{registrationPacket.registration_packet}</pre></div><div className="form-actions"><button className="button" onClick={async () => { await navigator.clipboard.writeText(registrationPacket.configuration_commands.join('\n')); setCopiedRegistration(true) }}>{copiedRegistration ? 'Copied' : 'Copy commands'}</button><button className="button primary" onClick={() => setRegistrationPacket(null)}>Close</button></div></Modal>}
  </>
}

export default App
